bounded_host_request.command:
set -euo pipefail
gay="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])gaybbs([-_]|$)' || true)"
test "$(printf '%s\n' "$gay" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_GROUP_NOT_UNIQUE; exit 61; }
state_dir="$HOME/.local/state/gace-stk04";receipt="$state_dir/creator_dm_2373696859.pin"
test -f "$receipt" || { echo STK04_RECEIPT_MISSING; exit 62; }
exec 9>"$state_dir/creator_dm_2373696859.lock";flock -n 9 || exit 63
status="$(cat "$receipt")"
if [ "$status" = "PINNED" ];then echo STK04_ALREADY_PINNED;exit 0;fi
if [ "$status" = "NEEDS_RECONCILE" ];then
 echo POSTED:4652 > "$receipt"
elif [ "$status" != "POSTED:4652" ];then
 echo "STK04_RECEIPT_CONFLICT";exit 64
fi
out="$(mktemp /tmp/gace-stk04-edit.XXXXXXXX)";trap 'rm -f "$out"' EXIT
if docker exec -i "$gay" node --input-type=module - >"$out" 2>&1 <<'STK04_RECONCILE_NODE'
import fs from "node:fs";import https from "node:https";
const f=process.env.BOT_TOKEN_FILE;
if(!f?.startsWith("/")){console.error("STK04_AUTH_CONFIG_MISSING");process.exit(2)}
const token=fs.readFileSync(f,"utf8").trim();
const api=(method,obj)=>new Promise((resolve,reject)=>{
const b=JSON.stringify(obj);
const req=https.request({hostname:"api.telegram.org",port:443,family:4,path:"/bot"+token+"/"+method,method:"POST",headers:{"Content-Type":"application/json","Content-Length":Buffer.byteLength(b)},timeout:12000},resp=>{
let s="";resp.on("data",d=>{if(s.length<65536)s+=d});resp.on("end",()=>{try{const j=JSON.parse(s);if(j.ok!==true)reject(Error("STK04_"+method+"_REJECTED_"+String(j.error_code??0)));else resolve(j.result)}catch(e){reject(e)}})
});req.on("timeout",()=>req.destroy(Error("STK04_API_TIMEOUT")));req.on("error",e=>reject(Error("STK04_NETWORK_"+String(e.code??"UNKNOWN"))));req.end(b);
});
try{
const me=await api("getMe",{});
if(me.username?.toLowerCase()!=="gaybbs_bot"||me.is_bot!==true)throw Error("STK04_WRONG_SENDER");
const m=await api("editMessageText",{
 chat_id:-1002373696859,message_id:4652,
 text:"🎨 ステッカー作成・投稿はこちら\n下のボタンからCreateVdobotのDMを開いてください。\n\n✅ ステッカー投稿メニューに移動",
 reply_markup:{inline_keyboard:[[{text:"🎨 投稿はこちら",url:"https://t.me/CreateVdobot?start=sticker"}]]}
});
console.log("STK04_EDIT_RETURN_CHAT_ID="+String(m?.chat?.id??"MISSING"));
console.log("STK04_EDIT_RETURN_MESSAGE_ID="+String(m?.message_id??"MISSING"));
console.log("STK04_EDIT_RETURN_THREAD_ID="+String(m?.message_thread_id??"MISSING"));
console.log("STK04_EDIT_RETURN_IS_TOPIC="+String(m?.is_topic_message===true));
console.log("STK04_EDIT_RETURN_REPLY_ID="+String(m?.reply_to_message?.message_id??"MISSING"));
const button=m?.reply_markup?.inline_keyboard?.[0]?.[0]?.url;
console.log("STK04_EDIT_RETURN_BUTTON="+(button==="https://t.me/CreateVdobot?start=sticker"?"PASS":"NOT_VERIFIED"));
if(Number(m?.chat?.id)!==-1002373696859||m?.message_id!==4652||m?.is_topic_message!==true||
   m?.message_thread_id!==4291||m?.from?.id!==me.id||button!=="https://t.me/CreateVdobot?start=sticker"||
   (m?.reply_to_message?.message_id!==undefined&&m.reply_to_message.message_id!==4640)) {
 console.log("STK04_PIN_BLOCKED_BY_TOPIC_VERIFICATION");
 process.exitCode=3;
}else{
 const res=await api("pinChatMessage",{chat_id:-1002373696859,message_id:4652,disable_notification:true});
 if(res!==true)throw Error("STK04_PIN_RESULT_NOT_TRUE");
 console.log("STK04_TELEGRAM_PIN_ACK=PASS");
 console.log("STK04_PINNED_MESSAGE_ID=4652");
}
}catch(e){console.error(String(e.message||"STK04_UNCLASSIFIED").replace(/[^A-Za-z0-9_]/g,"_"));process.exitCode=1}

STK04_RECONCILE_NODE
then
 grep '^STK04_' "$out" || true
 if grep -qx 'STK04_TELEGRAM_PIN_ACK=PASS' "$out";then
  echo PINNED > "$receipt"
  echo STK04_PIN_RECEIPT_PERSISTED
 else
  echo STK04_PIN_API_ACK_MISSING;exit 65
 fi
else
 grep '^STK04_' "$out" || true
 echo STK04_ORIGINAL_MESSAGE_PRESERVED_NO_RESEND
 exit 66
fi
